let DB=JSON.parse(JSON.stringify(EMBED));
const $=id=>document.getElementById(id);
function rows(name){return DB[name]?.rows||[]}
function num(v){let x=Number(v);return v==null||v===''||!Number.isFinite(x)?null:x}
function avg(a){a=a.filter(Number.isFinite);return a.length?a.reduce((x,y)=>x+y,0)/a.length:null}
function f(x,d=2){return x==null||!Number.isFinite(x)?'—':Number(x).toFixed(d)}
function put(id,v){$(id).textContent=v}
function base(id){let c=$(id),w=c.clientWidth||500,h=c.clientHeight||245,d=window.devicePixelRatio||1;c.width=w*d;c.height=h*d;let x=c.getContext('2d');x.scale(d,d);x.clearRect(0,0,w,h);return{x,w,h}}
function blank(x,w,h,t){x.fillStyle='#718293';x.textAlign='center';x.font='12px Arial';x.fillText(t,w/2,h/2);x.textAlign='left'}
function line(id,labels,series){let {x,w,h}=base(id),all=series.flatMap(s=>s.v).filter(Number.isFinite);if(!all.length)return blank(x,w,h,'No data available');let lo=Math.min(...all),hi=Math.max(...all),rg=hi-lo||1,L=48,R=12,T=14,B=30,pw=w-L-R,ph=h-T-B;x.font='10px Arial';for(let i=0;i<5;i++){let y=T+i*ph/4;x.strokeStyle='#e3eaee';x.beginPath();x.moveTo(L,y);x.lineTo(w-R,y);x.stroke();x.fillStyle='#748595';x.fillText(f(hi-i*rg/4,1),3,y+3)}series.forEach((s,j)=>{x.strokeStyle=['#176b87','#159b91','#e59a42'][j%3];x.lineWidth=2;x.beginPath();let started=false;s.v.forEach((v,i)=>{if(!Number.isFinite(v)){started=false;return}let px=L+(s.v.length<2?0:i/(s.v.length-1)*pw),py=T+(hi-v)/rg*ph;if(!started){x.moveTo(px,py);started=true}else x.lineTo(px,py)});x.stroke()});x.fillStyle='#718293';x.fillText(labels[0]||'',L,h-9);x.textAlign='right';x.fillText(labels.at(-1)||'',w-R,h-9);x.textAlign='left'}
function scatter(id,data,key){let{x,w,h}=base(id),p=data.map(r=>({x:num(r.longitude),y:num(r.latitude),v:num(r[key])})).filter(a=>a.x!==null&&a.y!==null&&a.v!==null);if(!p.length)return blank(x,w,h,'No coordinate data');let xs=p.map(a=>a.x),ys=p.map(a=>a.y),vs=p.map(a=>a.v),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),vmin=Math.min(...vs),vmax=Math.max(...vs);x.strokeStyle='#dbe5ea';x.strokeRect(35,12,w-48,h-42);p.forEach(a=>{let xx=35+(a.x-xmin)/(xmax-xmin||1)*(w-48),yy=h-30-(a.y-ymin)/(ymax-ymin||1)*(h-42),t=(a.v-vmin)/(vmax-vmin||1);x.fillStyle=`rgb(${Math.round(20+210*t)},${Math.round(105+55*(1-t))},${Math.round(170-100*t)})`;x.beginPath();x.arc(xx,yy,4,0,7);x.fill()});x.fillStyle='#708392';x.font='10px Arial';x.fillText('Longitude →',w/2,h-8)}
function table(id,html){$(id).innerHTML=html||'<tr><td class="empty">No records</td></tr>'}
function render(){
const m=rows('CapeTown_AI_Monthly_Climate_2002_2025.csv'),a=rows('CapeTown_AI_Annual_Climate_2002_2025.csv'),s=rows('Spatial_Climate_Data_Cleaned.csv').length?rows('Spatial_Climate_Data_Cleaned.csv'):rows('CapeTown_AI_Forecast_Geographic_Data.csv');
const dates=m.map(r=>r.date);put('kRecords',m.length.toLocaleString());put('kPeriod',dates.length?dates[0]+' to '+dates.at(-1):'No monthly data');
put('kRain',f(avg(m.map(r=>num(r.rainfall_mm))),1));put('kTemp',f(avg(m.map(r=>num(r.temperature_c))),2));put('kSoil',f(avg(m.map(r=>num(r.soil_moisture_m3m3))),3));put('kNdvi',f(avg(m.map(r=>num(r.ndvi))),3));
line('cRain',dates,[{v:m.map(r=>num(r.rainfall_mm))}]);line('cTemp',dates,[{v:m.map(r=>num(r.temperature_c))}]);line('cSoil',dates,[{v:m.map(r=>num(r.soil_moisture_m3m3))}]);line('cNdvi',dates,[{v:m.map(r=>num(r.ndvi))}]);
let years=a.map(r=>String(r.year));line('aRain',years,[{v:a.map(r=>num(r.annual_rainfall_mm))}]);line('aTemp',years,[{v:a.map(r=>num(r.annual_temperature_c))}]);
let trends=rows('Annual_Climate_Trends.csv');table('trendRows',trends.map(r=>`<tr><td>${r.variable}</td><td>${f(num(r.linear_slope_per_year),5)}</td><td>${f(num(r.linear_slope_per_decade),4)}</td><td>${r.first_year}–${r.last_year}</td><td>${r.observations}</td></tr>`).join(''));
scatter('sRain',s,'mean_annual_rainfall_mm');scatter('sTemp',s,'mean_temperature_c');scatter('sSoil',s,'mean_soil_moisture_m3m3');scatter('sNdvi',s,'mean_ndvi');
let met=rows('Model_Evaluation_Metrics.csv');table('metricRows',met.map(r=>`<tr><td>${r.variable}</td><td>${r.model}</td><td>${f(num(r.MAE),3)}</td><td>${f(num(r.RMSE),3)}</td><td>${f(num(r.R2),3)}</td><td>${r.test_samples}</td></tr>`).join(''));
let p=rows('Test_Set_Predictions.csv'),pd=p.map(r=>r.forecast_target_date);line('predRain',pd,[{v:p.map(r=>num(r.observed_rainfall_mm))},{v:p.map(r=>num(r.predicted_rainfall_mm))},{v:p.map(r=>num(r.rainfall_climatology_mm))}]);line('predTemp',pd,[{v:p.map(r=>num(r.observed_temperature_c))},{v:p.map(r=>num(r.predicted_temperature_c))},{v:p.map(r=>num(r.temperature_climatology_c))}]);
$('metricInsight').textContent='Evaluation contains '+(met[0]?.test_samples||'—')+' test samples per target. Series order in charts: observed, Random Forest, seasonal climatology.';
let rf=met.find(r=>r.variable==='rainfall'&&r.model==='Random Forest'),rb=met.find(r=>r.variable==='rainfall'&&r.model==='Seasonal climatology'),tf=met.find(r=>r.variable==='temperature'&&r.model==='Random Forest'),tb=met.find(r=>r.variable==='temperature'&&r.model==='Seasonal climatology');
$('interpretation').innerHTML=`<li>Rainfall: Random Forest MAE ${f(num(rf?.MAE),2)} mm versus seasonal climatology ${f(num(rb?.MAE),2)} mm; the seasonal baseline has a marginally lower MAE.</li><li>Rainfall R² is ${f(num(rf?.R2),3)} for Random Forest and ${f(num(rb?.R2),3)} for the seasonal baseline.</li><li>Temperature: Random Forest MAE ${f(num(tf?.MAE),3)} °C versus seasonal climatology ${f(num(tb?.MAE),3)} °C; the seasonal baseline performs marginally better on the supplied metrics.</li><li>Temperature R² is ${f(num(tf?.R2),3)} for Random Forest and ${f(num(tb?.R2),3)} for the seasonal baseline.</li>`;
const f12=rows('CapeTown_Experimental_12_Month_Forecast.csv'),f6=rows('CapeTown_6_Month_Climate_Forecast.csv');
line('f12',f12.map(r=>r.date),[{v:f12.map(r=>num(r.predicted_rainfall_mm))},{v:f12.map(r=>num(r.predicted_temperature_c))}]);
line('f6',f6.map(r=>r.date),[{v:f6.map(r=>num(r.rainfall_mm))},{v:f6.map(r=>num(r.temperature_c))}]);
table('f12Rows',f12.map(r=>`<tr><td>${r.date}</td><td>${f(num(r.predicted_rainfall_mm),1)}</td><td>${f(num(r.predicted_temperature_c),1)}</td></tr>`).join(''));
table('f6Rows',f6.map(r=>`<tr><td>${r.date}</td><td>${f(num(r.rainfall_mm),1)}</td><td>${f(num(r.temperature_c),1)}</td></tr>`).join(''));
let nm=rows('Experimental_Next_Month_Prediction.csv')[0];$('nextMonth').innerHTML=nm?`<div><div class="klabel">Target date</div><div class="value">${nm.forecast_target_date}</div></div><div><div class="klabel">Experimental rainfall</div><div class="value">${f(num(nm.rainfall_mm),2)} mm</div></div><div><div class="klabel">Experimental temperature</div><div class="value">${f(num(nm.temperature_c),2)} °C</div></div>`:'<div class="empty">No next-month output in package</div>';
let imp=rows('Feature_Importance.csv');for(let [id,target] of [['impRain','rainfall'],['impTemp','temperature']]){let z=imp.filter(r=>r.variable===target).sort((a,b)=>num(b.importance)-num(a.importance)).slice(0,12).reverse(),{x,w,h}=base(id),max=Math.max(...z.map(r=>num(r.importance)||0),.001);z.forEach((r,i)=>{let y=10+i*(h-20)/z.length;x.fillStyle='#176b87';x.fillRect(145,y,((num(r.importance)||0)/max)*(w-170),12);x.fillStyle='#526779';x.font='10px Arial';x.fillText(r.feature.slice(0,23),4,y+10);x.fillText(f(num(r.importance),3),w-34,y+10)})}
let q=rows('Data_Quality_Report (1).csv');table('qualityRows',q.map(r=>`<tr><td>${r.column}</td><td>${r.missing_values}</td></tr>`).join(''));
let imgs=Object.entries(DB).filter(([k,v])=>v.type==='image');$('gallery').innerHTML=imgs.map(([k,v])=>`<figure><img loading="lazy" src="${v.data}" alt="${k}"><figcaption>${k}</figcaption></figure>`).join('');
$('inventory').innerHTML=Object.entries(DB).map(([k,v])=>`<div class="fileitem">${k}<br><b>${v.type==='csv'?v.rows.length+' rows':v.type==='image'?'PNG figure':v.type==='model'?'Joblib model · '+(v.bytes/1048576).toFixed(2)+' MB':'JSON metadata'}</b></div>`).join('');
$('state').textContent=Object.keys(DB).length+' files available';
}
function parseCsv(t){let lines=t.trim().split(/\r?\n/);if(!lines.length)return[];let split=l=>{let out=[],s='',q=false;for(let i=0;i<l.length;i++){let c=l[i];if(c==='"'){if(q&&l[i+1]==='"'){s+='"';i++}else q=!q}else if(c===','&&!q){out.push(s);s=''}else s+=c}out.push(s);return out};let h=split(lines.shift());return lines.map(l=>{let a=split(l),o={};h.forEach((k,i)=>o[k]=a[i]??'');return o})}
async function ingest(name,file){let ext=name.split('.').pop().toLowerCase();if(ext==='csv')DB[name]={type:'csv',rows:parseCsv(await file.text())};else if(ext==='json')DB[name]={type:'json',data:JSON.parse(await file.text())};else if(ext==='png'){let url=URL.createObjectURL(file);let b=await fetch(url).then(r=>r.blob());let reader=new FileReader();DB[name]={type:'image',data:await new Promise(res=>{reader.onload=()=>res(reader.result);reader.readAsDataURL(b)})};URL.revokeObjectURL(url)}else if(ext==='joblib')DB[name]={type:'model',bytes:file.size}}
$('importBtn').onclick=async()=>{try{let zip=$('zipUpload').files[0],multi=[...$('multiUpload').files],count=0;if(zip){if(!window.JSZip)throw Error('ZIP import requires an internet connection to load the JSZip library.');let z=await JSZip.loadAsync(zip);for(let [path,obj] of Object.entries(z.files)){if(obj.dir)continue;let name=path.split('/').pop();if(!/\.(csv|json|png|joblib)$/i.test(name))continue;let blob=await obj.async('blob');await ingest(name,blob);count++}}for(let file of multi){await ingest(file.name,file);count++}if(!count)throw Error('Choose a ZIP archive or one or more supported files first.');render();$('uploadStatus').textContent='Imported '+count+' file(s). Matching dashboard sections have been refreshed.'}catch(e){$('uploadStatus').textContent='Import error: '+e.message}};
$('resetBtn').onclick=()=>{DB=JSON.parse(JSON.stringify(EMBED));render();$('zipUpload').value='';$('multiUpload').value='';$('uploadStatus').textContent='Restored the original attached ZIP package.'};
window.addEventListener('resize',()=>render());
render();
